   123→// Insert an item into the trie.
   124→func (m *SparseMerkleTrie) Insert(item []byte, index int) error {
   125→	if index < 0 {
   126→		return fmt.Errorf("negative index provided: %d", index)
   127→	}
   128→	for index >= len(m.branches[0]) {
   129→		m.branches[0] = append(m.branches[0], ZeroHashes[0][:])
   130→	}
   131→	someItem := bytesutil.ToBytes32(item)
   132→	m.branches[0][index] = someItem[:]
   133→	if index >= len(m.originalItems) {
   134→		m.originalItems = append(m.originalItems, someItem[:])
   135→	} else {
   136→		m.originalItems[index] = someItem[:]
   137→	}
   138→	currentIndex := index
   139→	root := bytesutil.ToBytes32(item)
   140→	for i := 0; i < int(m.depth); i++ {
   141→		isLeft := currentIndex%2 == 0
   142→		neighborIdx := currentIndex ^ 1
   143→		var neighbor []byte
   144→		if neighborIdx >= len(m.branches[i]) {
   145→			neighbor = ZeroHashes[i][:]
   146→		} else {
   147→			neighbor = m.branches[i][neighborIdx]
   148→		}
   149→		if isLeft {
   150→			parentHash := hash.Hash(append(root[:], neighbor...))
   151→			root = parentHash
   152→		} else {
   153→			parentHash := hash.Hash(append(neighbor, root[:]...))
   154→			root = parentHash
   155→		}
   156→		parentIdx := currentIndex / 2
   157→		if len(m.branches[i+1]) == 0 || parentIdx >= len(m.branches[i+1]) {
   158→			newItem := root
   159→			m.branches[i+1] = append(m.branches[i+1], newItem[:])
   160→		} else {
   161→			newItem := root
   162→			m.branches[i+1][parentIdx] = newItem[:]
   163→		}
   164→		currentIndex = parentIdx
   165→	}
   166→	return nil
   167→}
