   195→// ToProto converts the underlying trie into its corresponding
   196→// proto object
   197→func (m *SparseMerkleTrie) ToProto() *protodb.SparseMerkleTrie {
   198→	trie := &protodb.SparseMerkleTrie{
   199→		Depth:         uint64(m.depth),
   200→		Layers:        make([]*protodb.TrieLayer, len(m.branches)),
   201→		OriginalItems: m.originalItems,
   202→	}
   203→	for i, l := range m.branches {
   204→		trie.Layers[i] = &protodb.TrieLayer{
   205→			Layer: l,
   206→		}
   207→	}
   208→	return trie
   209→}
