   211→// VerifyMerkleProofWithDepth verifies a Merkle branch against a root of a trie.
   212→func VerifyMerkleProofWithDepth(root, item []byte, merkleIndex uint64, proof [][]byte, depth uint64) bool {
   213→	if uint64(len(proof)) != depth+1 {
   214→		return false
   215→	}
   216→	node := bytesutil.ToBytes32(item)
   217→	for i := uint64(0); i <= depth; i++ {
   218→		if (merkleIndex & 1) == 1 {
   219→			node = hash.Hash(append(proof[i], node[:]...))
   220→		} else {
   221→			node = hash.Hash(append(node[:], proof[i]...))
   222→		}
   223→		merkleIndex /= 2
   224→	}
   225→	return bytes.Equal(root, node[:])
   226→}
   227→
   228→// VerifyMerkleProof given a trie root, a leaf, the generalized merkle index
   229→// of the leaf in the trie, and the proof itself.
   230→func VerifyMerkleProof(root, item []byte, merkleIndex uint64, proof [][]byte) bool {
   231→	if len(proof) == 0 {
   232→		return false
   233→	}
   234→	return VerifyMerkleProofWithDepth(root, item, merkleIndex, proof, uint64(len(proof)-1))
   235→}
