   263→// ProofFromMerkleLayers creates a proof starting at the leaf index of the merkle layers.
   264→func ProofFromMerkleLayers(layers [][][]byte, startingLeafIndex int) [][]byte {
   265→	// The merkle tree structure looks as follows:
   266→	// [[r1, r2, r3, r4], [parent1, parent2], [root]]
   267→	proof := make([][]byte, 0)
   268→	currentIndex := startingLeafIndex
   269→	for i := 0; i < len(layers)-1; i++ {
   270→		neighborIdx := currentIndex ^ 1
   271→		neighbor := layers[i][neighborIdx]
   272→		proof = append(proof, neighbor)
   273→		currentIndex = currentIndex / 2
   274→	}
   275→	return proof
   276→}
