    70→// Merkleize with log(N) space allocation
    71→// This method will panic when count > limit.
    72→func Merkleize(hasher Hasher, count, limit uint64, leaf func(i uint64) []byte) (out [32]byte) {
    73→	if count > limit {
    74→		panic("merkleizing list that is too large, over limit") // lint:nopanic -- Panic is communicated in godoc commentary.
    75→	}
    76→	if limit == 0 {
    77→		return
    78→	}
    79→	if limit == 1 {
    80→		if count == 1 {
    81→			copy(out[:], leaf(0))
    82→		}
    83→		return
    84→	}
    85→	depth := Depth(count)
    86→	limitDepth := Depth(limit)
    87→	tmp := make([][32]byte, limitDepth+1)
    88→
    89→	j := uint8(0)
    90→	var hArr [32]byte
    91→	h := hArr[:]
    92→
    93→	merge := func(i uint64) {
    94→		// merge back up from bottom to top, as far as we can
    95→		for j = 0; ; j++ {
    96→			// stop merging when we are in the left side of the next combi
    97→			if i&(uint64(1)<<j) == 0 {
    98→				// if we are at the count, we want to merge in zero-hashes for padding
    99→				if i == count && j < depth {
   100→					v := hasher.Combi(hArr, trie.ZeroHashes[j])
   101→					copy(h, v[:])
   102→				} else {
   103→					break
   104→				}
   105→			} else {
   106→				// keep merging up if we are the right side
   107→				v := hasher.Combi(tmp[j], hArr)
   108→				copy(h, v[:])
   109→			}
   110→		}
   111→		// store the merge result (may be no merge, i.e. bottom leaf node)
   112→		copy(tmp[j][:], h)
   113→	}
   114→
   115→	// merge in leaf by leaf.
   116→	for i := uint64(0); i < count; i++ {
   117→		copy(h, leaf(i))
   118→		merge(i)
   119→	}
   120→
   121→	// complement with 0 if empty, or if not the right power of 2
   122→	if (uint64(1) << depth) != count {
   123→		copy(h, trie.ZeroHashes[0][:])
   124→		merge(count)
   125→	}
   126→
   127→	// the next power of two may be smaller than the ultimate virtual size,
   128→	// complement with zero-hashes at each depth.
   129→	for j := depth; j < limitDepth; j++ {
   130→		tmp[j+1] = hasher.Combi(tmp[j], trie.ZeroHashes[j])
   131→	}
   132→
   133→	return tmp[limitDepth]
   134→}
