   137→// elements.
   138→func MerkleizeVector(elements [][32]byte, length uint64) [32]byte {
   139→	depth := Depth(length)
   140→	// Return zerohash at depth
   141→	if len(elements) == 0 {
   142→		return trie.ZeroHashes[depth]
   143→	}
   144→	for i := uint8(0); i < depth; i++ {
   145→		layerLen := len(elements)
   146→		oddNodeLength := layerLen%2 == 1
   147→		if oddNodeLength {
   148→			zerohash := trie.ZeroHashes[i]
   149→			elements = append(elements, zerohash)
