    19→// ActivateValidatorWithEffectiveBalance updates validator's effective balance, and if it's above MaxEffectiveBalance, validator becomes active in genesis.
    20→func ActivateValidatorWithEffectiveBalance(beaconState state.BeaconState, deposits []*ethpb.Deposit) (state.BeaconState, error) {
    21→	for _, d := range deposits {
    22→		pubkey := d.Data.PublicKey
    23→		index, ok := beaconState.ValidatorIndexByPubkey(bytesutil.ToBytes48(pubkey))
    24→		// In the event of the pubkey not existing, we continue processing the other
    25→		// deposits.
    26→		if !ok {
    27→			continue
    28→		}
    29→		balance, err := beaconState.BalanceAtIndex(index)
    30→		if err != nil {
    31→			return nil, err
    32→		}
    33→		validator, err := beaconState.ValidatorAtIndex(index)
    34→		if err != nil {
    35→			return nil, err
    36→		}
    37→		validator.EffectiveBalance = math.Min(balance-balance%params.BeaconConfig().EffectiveBalanceIncrement, params.BeaconConfig().MaxEffectiveBalance)
    38→		if validator.EffectiveBalance ==
    39→			params.BeaconConfig().MaxEffectiveBalance {
    40→			validator.ActivationEligibilityEpoch = 0
    41→			validator.ActivationEpoch = 0
    42→		}
    43→		if err := beaconState.UpdateValidatorAtIndex(index, validator); err != nil {
    44→			return nil, err
    45→		}
    46→	}
    47→	return beaconState, nil
    48→}
