   100→// VerifyDeposit verifies the deposit data and signature given the beacon state and deposit information
   101→func VerifyDeposit(beaconState state.ReadOnlyBeaconState, deposit *ethpb.Deposit) error {
   102→	// Verify Merkle proof of deposit and deposit trie root.
   103→	if deposit == nil || deposit.Data == nil {
   104→		return errors.New("received nil deposit or nil deposit data")
   105→	}
   106→	eth1Data := beaconState.Eth1Data()
   107→	if eth1Data == nil {
   108→		return errors.New("received nil eth1data in the beacon state")
   109→	}
   110→
   111→	receiptRoot := eth1Data.DepositRoot
   112→	leaf, err := deposit.Data.HashTreeRoot()
   113→	if err != nil {
   114→		return errors.Wrap(err, "could not tree hash deposit data")
   115→	}
   116→	if ok := trie.VerifyMerkleProofWithDepth(
   117→		receiptRoot,
   118→		leaf[:],
   119→		beaconState.Eth1DepositIndex(),
   120→		deposit.Proof,
   121→		params.BeaconConfig().DepositContractTreeDepth,
   122→	); !ok {
   123→		return fmt.Errorf(
   124→			"deposit merkle branch of deposit root did not verify for root: %#x",
   125→			receiptRoot,
   126→		)
   127→	}
   128→
   129→	return nil
   130→}
